var l=[{title:`Προπόνηση στη ζέστη`,text:`Η ζέστη και η υγρασία μπορούν να κάνουν μια εύκολη συνεδρία να αισθάνεται πολύ πιο δύσκολη. Διαλέξτε πιο δροσερές ώρες και σκιερές διαδρομές, ξεκινήστε ήπια και πίνετε αρκετό νερό για τις συνθήκες. Το CDC συμβουλεύει να σταματάτε και να πηγαίνετε σε δροσερό μέρος αν νιώσετε λιποθυμία ή αδυναμία. Η σύγχυση, η κατάρρευση ή η πιθανή θερμοπληξία χρειάζονται επείγουσα βοήθεια.`},{title:`Κρύες, βροχερές και θυελλώδεις μέρες`,text:`Φορέστε στρώσεις που μπορείτε να βγάλετε και καλύψτε το εκτεθειμένο δέρμα όταν κάνει κρύο. Η βροχή και ο ιδρώτας μπορούν να κάνουν τα ρούχα και τις επιφάνειες επικίνδυνα κρύα, και το έντονο κρύο μπορεί να προκαλέσει κρυοπαγήματα ή υποθερμία. Ο πάγος ή η κακή ορατότητα είναι καλός λόγος να προπονηθείτε σε εσωτερικό χώρο εκείνη τη μέρα.`},{title:`Ελέγξτε το έδαφος`,text:`Ψάξτε για τρύπες, χαλαρά χαλίκια, ρίζες, ανώμαλο πεζοδρόμιο, κακό φωτισμό και διασταυρώσεις δρόμων. Οι κλίσεις αλλάζουν το φορτίο στους μυς και τις αρθρώσεις σας. Σε μια νέα διαδρομή, ξεκινήστε με άνετο ρυθμό, παραλείψτε τα σπριντ με όλη σας τη δύναμη και φορέστε παπούτσια με καλό κράτημα για την επιφάνεια.`},{title:`Ελέγξτε τον εξοπλισμό του πάρκου`,text:`Οι πάγκοι, τα κιγκλιδώματα και οι μπάρες pull-up μπορεί να είναι φθαρμένα από τον καιρό, χαλαρά ή να μην είναι φτιαγμένα για δυναμική άσκηση. Ψάξτε για αιχμηρές άκρες, σκουριά, σπασμένα εξαρτήματα και ασταθή στηρίγματα. Μην κρεμιέστε από οτιδήποτε εκτός αν είναι σαφώς φτιαγμένο να σας κρατήσει. Αφήστε άφθονο χώρο σε ποδηλάτες, παιδιά και άλλους χρήστες του πάρκου.`},{title:`Ελέγχετε ξανά κάθε φορά`,text:`Οι συνθήκες σε εξωτερικό χώρο αλλάζουν, οπότε κοιτάξτε ξανά κάθε φορά που βγαίνετε. Σε επικίνδυνο καιρό, περάστε σε συνεδρία σε εσωτερικό χώρο ή χαμηλής κρούσης, και διαλέξτε διαδρομές και κινήσεις που ταιριάζουν στο φως, στο έδαφος και στην εμπειρία σας.`}];var i=[{label:`CDC: άσκηση στη ζέστη`,url:`https://www.cdc.gov/heat-health/risk-factors/heat-and-athletes.html`},{label:`CDC: πρόληψη κρυοπαγημάτων και υποθερμίας`,url:`https://www.cdc.gov/winter-weather/prevention/preventing-frostbite.html`},{label:`Συστάσεις του CDC για τη σωματική δραστηριότητα ενηλίκων`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`}];var s={sections:l,sources:i};export{s as default,l as sections,i as sources};